function WhatsAppChatbot({ onClose, scrollToContact }) {
  const [step, setStep] = useState("start");
  const [history, setHistory] = useState([]);
  const chatRef = useRef(null);

  const current = chatFlow[step];

  useEffect(() => {
    if (chatRef.current) chatRef.current.scrollTop = chatRef.current.scrollHeight;
  }, [history, step]);

  const handleOption = (option) => {
    setHistory(h => [...h, { type: "user", text: option.label }]);
    setTimeout(() => {
      const next = chatFlow[option.next];
      if (next.action === "whatsapp") {
        window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=Hi! I'm interested in OptimTarget's services.`, "_blank");
        setHistory(h => [...h, { type: "bot", text: "Opening WhatsApp... See you there! 👋" }]);
      } else if (next.action === "form") {
        scrollToContact();
        setHistory(h => [...h, { type: "bot", text: next.message }]);
        onClose();
      } else {
        setHistory(h => [...h, { type: "bot", text: next.message }]);
        setStep(option.next);
      }
    }, 400);
  };

  return (
    <div style={{
      position: "fixed", bottom: 100, right: 24, width: 340, maxWidth: "calc(100vw - 48px)",
      background: "#fff", borderRadius: 20, boxShadow: "0 20px 60px rgba(0,0,0,0.20)",
      overflow: "hidden", zIndex: 1000, display: "flex", flexDirection: "column", maxHeight: 520,
    }}>
      {/* Header */}
      <div style={{ background: C.whatsapp, padding: "14px 18px", display: "flex", alignItems: "center", gap: 12 }}>
        <div style={{ width: 40, height: 40, borderRadius: "50%", background: "rgba(255,255,255,0.2)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20 }}>🤖</div>
        <div style={{ flex: 1 }}>
          <div style={{ color: "#fff", fontWeight: 700, fontSize: 14 }}>OptimTarget Assistant</div>
          <div style={{ color: "rgba(255,255,255,0.8)", fontSize: 12 }}>🟢 Online • Typically replies instantly</div>
        </div>
        <button onClick={onClose} style={{ background: "none", border: "none", color: "#fff", fontSize: 20, cursor: "pointer", padding: "0 4px" }}>✕</button>
      </div>

      {/* Messages */}
      <div ref={chatRef} style={{ flex: 1, overflowY: "auto", padding: "16px", background: "#ECE5DD", display: "flex", flexDirection: "column", gap: 10 }}>
        {/* Initial bot message */}
        <div style={{ display: "flex", gap: 8, alignItems: "flex-end" }}>
          <div style={{ width: 28, height: 28, borderRadius: "50%", background: C.whatsapp, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 14, flexShrink: 0 }}>🤖</div>
          <div style={{ background: "#fff", borderRadius: "12px 12px 12px 0", padding: "10px 14px", maxWidth: "85%", fontSize: 13, lineHeight: 1.6, color: "#1a1a1a", whiteSpace: "pre-line", boxShadow: "0 1px 2px rgba(0,0,0,0.1)" }}>
            {chatFlow.start.message}
          </div>
        </div>

        {/* History */}
        {history.map((msg, i) => (
          <div key={i} style={{ display: "flex", justifyContent: msg.type === "user" ? "flex-end" : "flex-start", gap: 8, alignItems: "flex-end" }}>
            {msg.type === "bot" && <div style={{ width: 28, height: 28, borderRadius: "50%", background: C.whatsapp, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 14, flexShrink: 0 }}>🤖</div>}
            <div style={{
              background: msg.type === "user" ? "#DCF8C6" : "#fff",
              borderRadius: msg.type === "user" ? "12px 12px 0 12px" : "12px 12px 12px 0",
              padding: "10px 14px", maxWidth: "85%", fontSize: 13, lineHeight: 1.6, color: "#1a1a1a",
              whiteSpace: "pre-line", boxShadow: "0 1px 2px rgba(0,0,0,0.1)"
            }}>
              {msg.text}
            </div>
          </div>
        ))}
      </div>

      {/* Options */}
      {chatFlow[step] && chatFlow[step].options.length > 0 && (
        <div style={{ padding: "12px", background: "#fff", borderTop: "1px solid #f0f0f0", display: "flex", flexDirection: "column", gap: 8 }}>
          {chatFlow[step].options.map((opt, i) => (
            <button key={i} onClick={() => handleOption(opt)} style={{
              background: "#fff", border: `1.5px solid ${C.whatsapp}`, color: C.whatsapp, borderRadius: 20,
              padding: "8px 14px", fontSize: 13, fontWeight: 600, cursor: "pointer", textAlign: "left",
              transition: "all 0.15s", fontFamily: "inherit",
            }}
              onMouseEnter={e => { e.target.style.background = C.whatsapp; e.target.style.color = "#fff"; }}
              onMouseLeave={e => { e.target.style.background = "#fff"; e.target.style.color = C.whatsapp; }}>
              {opt.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

